import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.164.1/build/three.module.js';

// GRAVEBOUND — a small open-world necromancer adventure.
const canvas = document.querySelector('#world');
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: false });
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.7));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.16;
const scene = new THREE.Scene();
scene.background = new THREE.Color('#a9a696');
scene.fog = new THREE.FogExp2('#9a998b', 0.0085);
const camera = new THREE.PerspectiveCamera(54, innerWidth / innerHeight, .1, 180);
const clock = new THREE.Clock();

const mat = (color, roughness=.9, opts={}) => new THREE.MeshStandardMaterial({ color, roughness, ...opts });
const mats = {
  earth: mat('#333c35'), grass: mat('#515b47'), darkGrass: mat('#303b35'), moss: mat('#707354'), stone: mat('#66685e'), paleStone: mat('#969183'), darkStone: mat('#34383a'), wood: mat('#4c4031'), bark: mat('#39352c'), leaf: mat('#35453c'), leaf2: mat('#49533e'), leaf3: mat('#5d6045'), bone: mat('#d7d0bc'), cloak: mat('#222a31'), cloakDark: mat('#151a20'), leather: mat('#594633'), metal: mat('#77796f',.42,{metalness:.45}), glow: mat('#7dd8d8',.22,{emissive:'#35bcc8',emissiveIntensity:2.5}), glowPurple: mat('#c8a0ed',.2,{emissive:'#8b4fd5',emissiveIntensity:2.2}), fire: mat('#f3b86e',.25,{emissive:'#dc6229',emissiveIntensity:2.2}), zombie: mat('#657365'), zombieDark: mat('#39453e'), eye: mat('#ef8b55',.3,{emissive:'#fa573c',emissiveIntensity:2}), black: mat('#101317'), water: mat('#243e45',.3,{emissive:'#13343a',emissiveIntensity:.3})
};
const hemi = new THREE.HemisphereLight('#d5d0bb','#343934',2.15); scene.add(hemi);
const sun = new THREE.DirectionalLight('#f0d9b2', 2.45); sun.position.set(-32,50,24); sun.castShadow=true; sun.shadow.mapSize.set(2048,2048); sun.shadow.camera.left=-55;sun.shadow.camera.right=55;sun.shadow.camera.top=55;sun.shadow.camera.bottom=-55;sun.shadow.bias=-.0002;scene.add(sun);
const fill = new THREE.DirectionalLight('#95a8b7',.75);fill.position.set(26,18,-28);scene.add(fill);
const world = new THREE.Group(); scene.add(world);
const ground = new THREE.Mesh(new THREE.PlaneGeometry(160,160), mats.earth); ground.rotation.x=-Math.PI/2;ground.position.y=-.12;ground.receiveShadow=true;world.add(ground);
const player = { group:new THREE.Group(), pos:new THREE.Vector3(0,0,10), vel:new THREE.Vector3(), hp:100,maxHp:100,mana:100,maxMana:100,xp:0,level:1,kills:0,souls:0,invuln:0,attackCd:0,stepCd:0,novaCd:0,summonCd:0,aim:new THREE.Vector3(0,0,-1), servants:[], alive:true };
const enemies=[], projectiles=[], effects=[], pickups=[], obelisks=[];
let started=false, ended=false, victory=false, elapsed=0, toastTimer=0, interactTarget=null, audioOn=true, audioCtx=null, pointer=new THREE.Vector2(), cameraRay=new THREE.Raycaster(), aimPoint=new THREE.Vector3(0,0,-8), worldTime=0;
const keys={};

function mesh(geometry, material, parent, x=0,y=0,z=0, cast=true){const m=new THREE.Mesh(geometry,material);m.position.set(x,y,z);m.castShadow=cast;m.receiveShadow=true;parent.add(m);return m;}
function sphere(r, material, parent, x,y,z, seg=12){return mesh(new THREE.SphereGeometry(r,seg,Math.max(7,Math.floor(seg*.7))),material,parent,x,y,z);}
function cyl(rt,rb,h,material,parent,x,y,z,segments=8){return mesh(new THREE.CylinderGeometry(rt,rb,h,segments),material,parent,x,y,z);}
function box(w,h,d,material,parent,x,y,z){return mesh(new THREE.BoxGeometry(w,h,d),material,parent,x,y,z);}
function rng(seed){let s=seed>>>0;return()=>{s=(s*1664525+1013904223)>>>0;return s/4294967296;}}
const rand=rng(82417);
function addFoliage(){
  // soft, broken clearings rather than an empty arena
  for(let i=0;i<95;i++){
    const x=(rand()-.5)*140,z=(rand()-.5)*140,d=Math.hypot(x,z-10);
    if(d<14 || (Math.abs(x)<4 && z<14&&z>-32))continue;
    const r=1+rand()*3.5; const patch=mesh(new THREE.CircleGeometry(r,8),rand()>.5?mats.grass:mats.darkGrass,world,x,-.085,z,false);patch.rotation.x=-Math.PI/2;patch.rotation.z=rand()*Math.PI;
  }
  // low polygon grass tufts
  const tuftGeo=new THREE.ConeGeometry(.12,.48,4);
  for(let i=0;i<460;i++){
    const x=(rand()-.5)*142,z=(rand()-.5)*142;if(Math.hypot(x,z-10)<11)continue;
    const t=mesh(tuftGeo,rand()>.5?mats.moss:mats.leaf,world,x,-.02,z,false);t.rotation.z=(rand()-.5)*.5;t.rotation.x=(rand()-.5)*.25;t.scale.setScalar(.6+rand()*1.5);
  }
  // old road stones run north into the mist
  for(let i=0;i<31;i++){
    const z=24-i*2.7,w=3.3+rand()*1.2;const p=box(w,.18,2.1,rand()>.45?mats.paleStone:mats.stone,world,(rand()-.5)*.7,.02,z);p.rotation.y=(rand()-.5)*.1;p.rotation.z=(rand()-.5)*.025;
  }
  // scattered slabs and broken masonry
  for(let i=0;i<43;i++){
    let x=(rand()-.5)*120,z=(rand()-.5)*120;if(Math.hypot(x,z-10)<12)continue;
    const b=box(.45+rand()*1.3,.25+rand()*.65,.45+rand()*1.5,rand()>.5?mats.stone:mats.darkStone,world,x,.05,z);b.rotation.set((rand()-.5)*.12,rand()*3,(rand()-.5)*.13);
  }
  // gnarled trees in clustered silhouettes
  for(let i=0;i<58;i++){
    const x=(rand()-.5)*132,z=(rand()-.5)*132;if(Math.hypot(x,z-10)<15)continue;
    const h=3.7+rand()*4.6,g=new THREE.Group();g.position.set(x,0,z);world.add(g);
    const trunk=cyl(.24,.5,h*.62,mats.bark,g,0,h*.31,0,6);trunk.rotation.z=(rand()-.5)*.17;
    for(let b=0;b<3;b++){const branch=cyl(.08,.2,h*.33,mats.bark,g,(rand()-.5)*.8,h*.47,(rand()-.5)*.5,5);branch.rotation.z=(rand()-.5)*.9;branch.rotation.x=(rand()-.5)*.55;}
    for(let c=0;c<5;c++){
      const crown=sphere(1.05+rand()*.75,rand()>.48?mats.leaf:mats.leaf2,g,(rand()-.5)*1.5,h*.64+rand()*1.1,(rand()-.5)*1.4,7);crown.scale.y=.8+rand()*.6;
    }
  }
  // standing stones and ruins around map edge
  for(let i=0;i<15;i++){
    let a=rand()*Math.PI*2,r=25+rand()*38,x=Math.cos(a)*r,z=10+Math.sin(a)*r;
    const s=box(.8+rand()*.6,2.5+rand()*2.2,.7+rand()*.5,mats.darkStone,world,x,1,z);s.rotation.z=(rand()-.5)*.17;s.rotation.y=rand()*2;
    box(1.25,.25,.9,mats.stone,world,x,2.4+rand()*1.4,z+.1).rotation.y=s.rotation.y;
  }
}
addFoliage();

function makePlayer(){
  const g=player.group;g.position.copy(player.pos);world.add(g);
  const shadow=mesh(new THREE.CircleGeometry(.65,16),mat('#111813',1,{transparent:true,opacity:.48}),g,0,.025,0,false);shadow.rotation.x=-Math.PI/2;
  const robe=mesh(new THREE.ConeGeometry(.68,1.52,7),mats.cloak,g,0,.92,0);robe.rotation.y=.35;
  const inner=mesh(new THREE.ConeGeometry(.4,1.15,6),mats.cloakDark,g,0,.9,-.08);
  const torso=sphere(.39,mats.cloak,g,0,1.65,0,9);torso.scale.set(.8,1.25,.63);
  const hood=sphere(.35,mats.cloakDark,g,0,2.19,0,9);hood.scale.set(.93,1.15,.85);
  // shadowed face and eerie eyes
  sphere(.22,mat('#111720'),g,0,2.12,-.14,8);
  sphere(.035,mats.glow,g,-.095,2.16,-.33,7);sphere(.035,mats.glow,g,.095,2.16,-.33,7);
  const shoulder1=sphere(.19,mats.leather,g,-.38,1.7,0,7),shoulder2=sphere(.19,mats.leather,g,.38,1.7,0,7);
  const arm1=cyl(.1,.14,.67,mats.cloak,g,-.48,1.31,0,6);arm1.rotation.z=-.2;
  const arm2=cyl(.1,.14,.67,mats.cloak,g,.48,1.34,0,6);arm2.rotation.z=.25;
  const belt=cyl(.42,.42,.12,mats.leather,g,0,1.17,0,8);
  const staff=new THREE.Group();staff.position.set(.66,0,-.05);g.add(staff);const stick=cyl(.045,.065,2.05,mats.wood,staff,0,1.12,0,6);stick.rotation.z=-.1;
  const orb=sphere(.17,mats.glow,staff,0,2.22,0,9);const ring=mesh(new THREE.TorusGeometry(.23,.018,5,14),mats.metal,staff,0,2.22,0);ring.rotation.x=Math.PI/2;
  const cloakFlap=mesh(new THREE.ConeGeometry(.55,.75,5),mats.cloakDark,g,0,.69,.38);cloakFlap.rotation.x=-.3;
  player.rig={robe,torso,hood,arm1,arm2,staff,orb,cloakFlap};
  const rune=mesh(new THREE.RingGeometry(.62,.68,36),mat('#75d5d8',.5,{transparent:true,opacity:.28,emissive:'#329ca3',emissiveIntensity:.7}),world,player.pos.x,.025,player.pos.z);rune.rotation.x=-Math.PI/2;player.rune=rune;
}
makePlayer();
function makeObelisk(x,z,index){
  const g=new THREE.Group();g.position.set(x,0,z);world.add(g);
  const base=cyl(1.13,1.28,.45,mats.darkStone,g,0,.22,0,7);
  const step=cyl(.92,1.03,.22,mats.paleStone,g,0,.53,0,7);
  const shaft=mesh(new THREE.CylinderGeometry(.48,.74,3.8,5),mats.stone,g,0,2.48,0);shaft.rotation.y=.3;
  const cap=mesh(new THREE.ConeGeometry(.62,.85,5),mats.darkStone,g,0,4.76,0);cap.rotation.y=.3;
  const rune=sphere(.2,mats.glow,g,0,2.55,-.49,8);rune.scale.set(.76,1.4,.28);
  const ring=mesh(new THREE.TorusGeometry(1.25,.035,6,40),mat('#80cbd1',.4,{transparent:true,opacity:.35,emissive:'#4fbfc7',emissiveIntensity:.8}),g,0,.06,0);ring.rotation.x=Math.PI/2;
  for(let i=0;i<5;i++){const c=cyl(.04,.04,.5,mats.glow,g,Math.cos(i*1.25)*.82,.9,Math.sin(i*1.25)*.82,5);c.rotation.z=Math.PI/2;}
  g.userData={index,awakened:false,rune,ring};obelisks.push(g);
  const label=makeWorldLabel(index===0?'THE WEEPING STONE':index===1?'THE HOLLOW WATCH':'THE SUNKEN ALTAR',x,z);g.userData.label=label;
}
function makeWorldLabel(text,x,z){
  const c=document.createElement('canvas');c.width=512;c.height=64;const ctx=c.getContext('2d');ctx.clearRect(0,0,512,64);ctx.font='600 25px Cinzel, serif';ctx.textAlign='center';ctx.fillStyle='#eee3ce';ctx.shadowColor='#080a0c';ctx.shadowBlur=8;ctx.fillText(text,256,39);
  const tex=new THREE.CanvasTexture(c);const sprite=new THREE.Sprite(new THREE.SpriteMaterial({map:tex,transparent:true,depthWrite:false}));sprite.position.set(x,5.5,z);sprite.scale.set(7.5,.95,1);world.add(sprite);return sprite;
}
makeObelisk(-17,-18,0);makeObelisk(18,-30,1);makeObelisk(21,17,2);

function makeEnemy(type='wretch',x=0,z=0){
  const g=new THREE.Group();g.position.set(x,0,z);world.add(g);
  const scale=type==='brute'?1.45:type==='wraith'?1.25:.9;
  const bodymat=type==='wraith'?mats.cloakDark:mats.zombie;
  const shadow=mesh(new THREE.CircleGeometry(.5*scale,12),mat('#10140f',1,{transparent:true,opacity:.46}),g,0,.022,0,false);shadow.rotation.x=-Math.PI/2;
  if(type==='wraith'){
    const sh=mesh(new THREE.ConeGeometry(.78,2.2,6),mat('#302842',.62,{transparent:true,opacity:.9,emissive:'#281040',emissiveIntensity:.3}),g,0,1.05,0);sh.rotation.y=.4;
    sphere(.42,mat('#454050'),g,0,2.02,0,8);sphere(.32,mat('#171521'),g,0,2.05,-.2,8);
    sphere(.07,mats.glowPurple,g,-.13,2.08,-.46,7);sphere(.07,mats.glowPurple,g,.13,2.08,-.46,7);
    for(let i=0;i<4;i++){const t=mesh(new THREE.ConeGeometry(.11,.7,5),mat('#343047'),g,(i-1.5)*.27,.28,(i%2)*.22);t.rotation.z=(i-1.5)*.28;}
  }else{
    const torso=sphere(.38*scale,bodymat,g,0,1.1*scale,0,8);torso.scale.set(.95,1.35,.72);
    sphere(.29*scale,mats.zombieDark,g,0,1.78*scale,-.03,8);
    sphere(.22*scale,mat('#292f2c'),g,0,1.82*scale,-.18,7);
    sphere(.035*scale,mats.eye,-1===1?g:g,-.085*scale,1.85*scale,-.385*scale,6);sphere(.035*scale,mats.eye,g,.085*scale,1.85*scale,-.385*scale,6);
    const armL=cyl(.09*scale,.14*scale,.76*scale,mats.zombieDark,g,-.46*scale,1.02*scale,-.06,5);armL.rotation.z=-.8;
    const armR=cyl(.09*scale,.14*scale,.78*scale,mats.zombieDark,g,.46*scale,1.08*scale,-.06,5);armR.rotation.z=.7;
    sphere(.15*scale,mats.zombieDark,g,-.7*scale,.7*scale,-.08,6);sphere(.15*scale,mats.zombieDark,g,.69*scale,.76*scale,-.08,6);
    const legL=cyl(.11*scale,.16*scale,.6*scale,mats.zombieDark,g,-.17*scale,.32*scale,0,5),legR=cyl(.11*scale,.16*scale,.6*scale,mats.zombieDark,g,.17*scale,.32*scale,0,5);legL.rotation.x=.1;legR.rotation.x=-.1;
  }
  g.scale.setScalar(scale);
  const hp=type==='brute'?105:type==='wraith'?250:52;
  const barbg=mesh(new THREE.PlaneGeometry(1.15,.09),mat('#171a1c'),g,0,2.7*scale,0,false);barbg.rotation.y=Math.PI;
  const bar=mesh(new THREE.PlaneGeometry(1.08,.055),mat(type==='wraith'?'#a56ade':'#c15e4e'),g,0,2.7*scale,.012,false);bar.rotation.y=Math.PI;
  const e={group:g,type,hp,maxHp:hp,speed:type==='wraith'?2.15:type==='brute'?1.05:1.55,damage:type==='wraith'?14:type==='brute'?18:10,attackCd:rand()*.7,walk:rand()*8,hit:0,bar};g.userData.enemy=e;enemies.push(e);return e;
}
// Restless dead guard each approach; one patrols the old road.
[[-12,-11,'wretch'],[-21,-21,'wretch'],[-9,-25,'brute'],[13,-21,'wretch'],[22,-33,'brute'],[25,-26,'wretch'],[16,13,'wretch'],[25,20,'brute'],[11,22,'wretch'],[-3,-7,'wretch'],[4,-14,'wretch']].forEach(([x,z,t])=>makeEnemy(t,x,z));
function makeServant(){
  const g=new THREE.Group();world.add(g);const robe=mesh(new THREE.ConeGeometry(.48,1.2,6),mats.bone,g,0,.68,0);robe.material=mat('#aeb5ab');sphere(.24,mats.bone,g,0,1.48,0,7);sphere(.13,mats.black,g,0,1.46,-.15,7);sphere(.028,mats.glow,g,-.06,1.48,-.27,6);sphere(.028,mats.glow,g,.06,1.48,-.27,6);
  const armL=cyl(.055,.085,.53,mats.bone,g,-.36,1.0,0,5);armL.rotation.z=-.45;const armR=cyl(.055,.085,.53,mats.bone,g,.36,1,0,5);armR.rotation.z=.45;
  const s={group:g,hp:60,attackCd:0,life:38,walk:rand()*6};player.servants.push(s);return s;
}
function spawnBoss(){
  if(player.bossSpawned)return;player.bossSpawned=true;
  const g=new THREE.Group();g.position.set(0,0,-45);world.add(g);
  const ring=mesh(new THREE.TorusGeometry(2.5,.11,8,48),mats.glowPurple,g,0,.12,0);ring.rotation.x=Math.PI/2;
  for(let i=0;i<8;i++){const stone=box(.6,2.7,.6,mats.darkStone,g,Math.cos(i*Math.PI/4)*3.1,1.1,Math.sin(i*Math.PI/4)*3.1);stone.rotation.z=(rand()-.5)*.15;}
  const glyph=mesh(new THREE.TorusGeometry(1.6,.035,5,40),mats.glowPurple,g,0,3.7,0);glyph.rotation.x=Math.PI/2;
  player.portal=g;player.boss=makeEnemy('wraith',0,-43);player.boss.group.scale.multiplyScalar(1.15);
  notify('THE WRAITH KING HAS AWAKENED');document.querySelector('#quest-title').textContent='The Last Silence';document.querySelector('#quest-desc').textContent='Defeat the Wraith King';document.querySelector('#bottom-hint').innerHTML='<span class="hint-dot"></span> The Wraith King waits beyond the old road.';
}

function notify(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');toastTimer=2.2;}
function sound(freq=220,duration=.12,type='sine',volume=.035){if(!audioOn)return;try{audioCtx ||= new (window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume();const o=audioCtx.createOscillator(),gain=audioCtx.createGain();o.type=type;o.frequency.setValueAtTime(freq,audioCtx.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(45,freq*.55),audioCtx.currentTime+duration);gain.gain.setValueAtTime(volume,audioCtx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(gain);gain.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration);}catch{}}
function makeBurst(pos,color='#78d9dc',count=13,size=.1){
  for(let i=0;i<count;i++){const m=sphere(size*(.6+rand()),mat(color,.45,{emissive:color,emissiveIntensity:1.6}),world,pos.x,pos.y,pos.z,6);const v=new THREE.Vector3((rand()-.5)*4,rand()*3,(rand()-.5)*4);effects.push({mesh:m,vel:v,life:.45+rand()*.45,max:.9,fade:true});}
}
function addRing(pos,color,r=1){const m=mesh(new THREE.TorusGeometry(.35,.045,5,24),mat(color,.4,{transparent:true,opacity:.8,emissive:color,emissiveIntensity:1.4}),world,pos.x,.22,pos.z);m.rotation.x=Math.PI/2;effects.push({mesh:m,life:.45,max:.45,expand:r,ring:true});}
function damageEnemy(e,amount,knock){if(!e||!enemies.includes(e))return;e.hp-=amount;e.hit=.16;e.bar.scale.x=Math.max(.02,e.hp/e.maxHp);e.bar.position.x=-(1-e.hp/e.maxHp)*.52;makeBurst(new THREE.Vector3(e.group.position.x,1.3,e.group.position.z),'#86d8d8',5,.07);if(knock){const d=e.group.position.clone().sub(player.group.position);d.y=0;d.normalize();e.group.position.addScaledVector(d,knock);}
  if(e.hp<=0)killEnemy(e);
}
function killEnemy(e){const i=enemies.indexOf(e);if(i<0)return;enemies.splice(i,1);makeBurst(new THREE.Vector3(e.group.position.x,1,e.group.position.z),e.type==='wraith'?'#ca9cf0':'#b8d5c7',23,.11);addRing(e.group.position,e.type==='wraith'?'#b889e1':'#86c7c9',1.8);world.remove(e.group);player.kills++;player.xp+=e.type==='wraith'?100:30;player.souls++;spawnPickup(e.group.position.x,e.group.position.z);sound(e.type==='wraith'?95:150,.28,'triangle',.05);checkLevel();if(e.type==='wraith'){finishGame(true);}}
function spawnPickup(x,z){const g=new THREE.Group();g.position.set(x,.5,z);world.add(g);const orb=sphere(.13,mats.glow,g,0,0,0,7);const ring=mesh(new THREE.TorusGeometry(.2,.025,5,14),mats.glow,g);ring.rotation.x=Math.PI/2;pickups.push({group:g,life:18,phase:rand()*8});}
function checkLevel(){const need=player.level===1?80:player.level===2?140:220;if(player.xp>=need){player.xp-=need;player.level++;player.maxHp+=15;player.hp=Math.min(player.maxHp,player.hp+30);player.maxMana+=10;player.mana=player.maxMana;notify(`SOULBOUND · LEVEL ${player.level}`);sound(430,.35,'sine',.05);}}
function fireBolt(){if(player.attackCd>0||!player.alive)return;player.attackCd=.34;const origin=player.group.position.clone().add(new THREE.Vector3(0,1.75,0));let dir=aimPoint.clone().sub(origin);dir.y=0;
  let nearest=null,dist=100;for(const e of enemies){const d=e.group.position.clone().sub(origin);d.y=0;const len=d.length(),dot=d.normalize().dot(dir.clone().normalize());if(dot>.89&&len<dist){dist=len;nearest=e;}}
  if(nearest&&dist<31){const d=nearest.group.position.clone().sub(origin);d.y=0;dir.copy(d.normalize());}
  dir.normalize();player.aim.copy(dir);player.group.rotation.y=Math.atan2(dir.x,dir.z)+Math.PI;
  const orb=sphere(.16,mats.glow,world,origin.x,origin.y,origin.z,8);const halo=mesh(new THREE.TorusGeometry(.22,.025,5,14),mats.glow,world,origin.x,origin.y,origin.z);halo.rotation.x=Math.PI/2;projectiles.push({mesh:orb,halo,vel:dir.multiplyScalar(24),life:1.35,damage:31,type:'bolt'});makeBurst(origin,'#78d8dc',4,.06);sound(330,.12,'triangle',.025);
}
function castNova(){if(player.novaCd>0||player.mana<55||!player.alive)return;player.mana-=55;player.novaCd=1.5;const p=player.group.position;addRing(p,'#c38ce8',8);makeBurst(new THREE.Vector3(p.x,.8,p.z),'#bb8ade',35,.13);for(const e of [...enemies])if(e.group.position.distanceTo(p)<7.8){damageEnemy(e,58,1.2);}for(let i=0;i<3;i++){const ring=mesh(new THREE.TorusGeometry(.5,.055,6,40),mat('#c38ce8',.4,{transparent:true,opacity:.8,emissive:'#ab69dc',emissiveIntensity:1.4}),world,p.x,.16+i*.18,p.z);ring.rotation.x=Math.PI/2;effects.push({mesh:ring,life:.55+i*.1,max:.8,expand:7.5,ring:true,delay:i*.08});}sound(125,.4,'sawtooth',.045);}
function summon(){if(player.summonCd>0||player.mana<35||!player.alive)return;player.mana-=35;player.summonCd=2.5;if(player.servants.length>=2){notify('TWO BONE SERVANTS ALREADY BOUND');return;}const s=makeServant();s.group.position.copy(player.group.position).add(new THREE.Vector3((rand()-.5)*2,.1,(rand()-.5)*2));makeBurst(s.group.position,'#b5e3df',18,.08);notify('A BONE SERVANT ANSWERS');sound(185,.32,'sine',.04);}
function wraithStep(){if(player.stepCd>0||!player.alive)return;let d=new THREE.Vector3((keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),0,(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0));if(d.lengthSq()<.1)d.copy(player.aim);d.normalize();player.pos.addScaledVector(d,5.2);player.pos.x=THREE.MathUtils.clamp(player.pos.x,-65,65);player.pos.z=THREE.MathUtils.clamp(player.pos.z,-67,65);player.group.position.copy(player.pos);player.stepCd=1.2;player.invuln=.45;addRing(player.pos,'#80dbe2',1.8);makeBurst(player.pos,'#80dbe2',15,.08);sound(470,.18,'sine',.035);}
function awaken(o){if(!o||o.userData.awakened)return;o.userData.awakened=true;o.userData.rune.material=mats.glowPurple;o.userData.ring.material=mat('#d1a5ef',.4,{transparent:true,opacity:.8,emissive:'#ad74de',emissiveIntensity:1.8});o.userData.label.material.color.set('#d7b2f3');for(let i=0;i<3;i++){const r=mesh(new THREE.TorusGeometry(1.3+i*.42,.035,5,40),mat('#80d8dc',.35,{transparent:true,opacity:.75,emissive:'#5cb9bf',emissiveIntensity:1.4}),world,o.position.x,.14+i*.2,o.position.z);r.rotation.x=Math.PI/2;effects.push({mesh:r,life:.7+i*.1,max:1,expand:3.5,ring:true,delay:i*.1});}makeBurst(o.position.clone().add(new THREE.Vector3(0,2,0)),'#9de2df',34,.12);player.mana=player.maxMana;player.hp=Math.min(player.maxHp,player.hp+20);player.xp+=45;player.souls+=3;checkLevel();notify('SOUL OBELISK AWAKENED · +3 SOULS');sound(520,.5,'sine',.055);updateQuest();}
function updateQuest(){const n=obelisks.filter(o=>o.userData.awakened).length;document.querySelector('#quest-progress').style.width=`${n/3*100}%`;document.querySelector('#quest-count').textContent=`${n} / 3 AWAKENED`;if(n===3){document.querySelector('#quest-title').textContent='The Last Silence';document.querySelector('#quest-desc').textContent='Find the Wraith King at the old road';document.querySelector('#bottom-hint').innerHTML='<span class="hint-dot"></span> The Wraith King waits beyond the old road.';spawnBoss();}}
function finishGame(win){if(ended)return;ended=true;victory=win;const m=document.querySelector('#end-modal');document.querySelector('#end-title').innerHTML=win?'DAWN<br><em>RETURNS</em>':'THE WILDS<br><em>CLAIM YOU</em>';document.querySelector('#end-copy').innerHTML=win?'The souls of Ashenmoor are free.<br>The old road is quiet at last.':'The dead return to their silence.<br>But the Ashen Wilds remain...';document.querySelector('#end-stats').innerHTML=`<div><strong>${player.kills}</strong>DEAD DEFEATED</div><div><strong>${player.level}</strong>SOUL LEVEL</div><div><strong>${player.souls}</strong>SOULS BOUND</div>`;m.classList.remove('hidden');}
function interact(){if(interactTarget){awaken(interactTarget);interactTarget=null;document.querySelector('#interact-prompt').style.display='none';return;}if(player.portal&&player.group.position.distanceTo(player.portal.position)<5&&!victory){notify('THE WRAITH KING MUST FALL');}}

// Distant moon and broken stone arches give the mist a horizon.
const moon=sphere(4,mat('#ddd6c2',.8,{emissive:'#c8c0aa',emissiveIntensity:.35}),scene,-38,30,-92,16);moon.material.transparent=true;moon.material.opacity=.8;
for(let i=0;i<8;i++){const x=-30+i*8,z=-51-(i%3)*1.5;const p=box(.7,3.8,.7,mats.darkStone,world,x,1.9,z);p.rotation.z=(i%2?.08:-.06);if(i%2===0)box(7,.35,.8,mats.darkStone,world,x+3.1,3.7,z);}

function update(dt){
  worldTime+=dt;elapsed+=dt;
  if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)document.querySelector('#toast').classList.remove('show');}
  player.attackCd=Math.max(0,player.attackCd-dt);player.stepCd=Math.max(0,player.stepCd-dt);player.novaCd=Math.max(0,player.novaCd-dt);player.summonCd=Math.max(0,player.summonCd-dt);player.invuln=Math.max(0,player.invuln-dt);
  if(!player.alive||ended)return;
  player.mana=Math.min(player.maxMana,player.mana+5.8*dt);
  const move=new THREE.Vector3((keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),(0),(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0));
  if(window.touchMove){move.x+=window.touchMove.x;move.z+=window.touchMove.y;}
  if(move.lengthSq()>1)move.normalize();
  const speed=keys.shift?8.3:5.1;player.pos.addScaledVector(move,speed*dt);player.pos.x=THREE.MathUtils.clamp(player.pos.x,-67,67);player.pos.z=THREE.MathUtils.clamp(player.pos.z,-68,67);player.group.position.copy(player.pos);
  if(move.lengthSq()>.02){const a=Math.atan2(move.x,move.z)+Math.PI;player.group.rotation.y=THREE.MathUtils.lerp(player.group.rotation.y,a,Math.min(1,dt*10));}
  player.rig.robe.rotation.z=Math.sin(worldTime*8)*(move.lengthSq()>.01?.035:.008);player.rig.arm1.rotation.x=Math.sin(worldTime*8)*.16;player.rig.arm2.rotation.x=-Math.sin(worldTime*8)*.16;player.rig.orb.material.emissiveIntensity=2+Math.sin(worldTime*4)*.7;
  // camera eases after the wandering necromancer, looking just ahead of her
  const desired=new THREE.Vector3(player.pos.x,player.pos.y+22,player.pos.z+19);camera.position.lerp(desired,1-Math.pow(.001,dt));camera.lookAt(player.pos.x,1.2,player.pos.z-1.6);
  // Face the cursor's ground point for responsive, understandable aim.
  const dir=aimPoint.clone().sub(player.pos);dir.y=0;if(dir.lengthSq()>.2){player.aim.copy(dir.normalize());if(window.mouseActive)player.group.rotation.y=Math.atan2(player.aim.x,player.aim.z)+Math.PI;}
  for(const o of obelisks){o.userData.rune.material.emissiveIntensity=o.userData.awakened?2.2+Math.sin(worldTime*2)*.7:1.1+Math.sin(worldTime*2.7+o.userData.index)*.7;o.userData.ring.rotation.z=worldTime*(o.userData.awakened?.28:.12);o.userData.label.material.opacity=THREE.MathUtils.clamp(1-player.pos.distanceTo(o.position)/36,.18,.9);}
  interactTarget=null;let nearest=4;for(const o of obelisks)if(!o.userData.awakened){const d=player.pos.distanceTo(o.position);if(d<nearest){nearest=d;interactTarget=o;}}
  const prompt=document.querySelector('#interact-prompt');if(interactTarget){prompt.style.display='flex';document.querySelector('#interact-text').textContent='AWAKEN SOUL OBELISK';}else prompt.style.display='none';
  // Basic enemies pursue within the mist. A brief tell precedes every strike.
  for(const e of [...enemies]){
    const ep=e.group.position,delta=player.pos.clone().sub(ep);delta.y=0;const dist=delta.length();e.attackCd-=dt;e.hit=Math.max(0,e.hit-dt);e.walk+=dt*(dist>1.5?7:2);e.group.position.y=Math.sin(e.walk)*.045;
    if(e.type==='wraith'){e.group.position.y=.35+Math.sin(worldTime*2.8)*.35;e.group.rotation.y=Math.sin(worldTime)*.22;}
    else if(dist<34){const d=delta.normalize();if(dist>1.65){ep.addScaledVector(d,e.speed*dt);e.group.rotation.y=Math.atan2(d.x,d.z)+Math.PI;}else if(e.attackCd<=0){e.attackCd=e.type==='brute'?1.65:1.15;if(player.invuln<=0){hurt(e.damage);}}}
    if(e.hit>0)e.group.scale.setScalar((e.type==='brute'?1.45:e.type==='wraith'?1.25:.9)*(1+Math.sin(e.hit*35)*.08));else if(e.type!=='wraith')e.group.scale.setScalar(e.type==='brute'?1.45:.9);
    if(e.type==='wraith'&&dist<2.8&&e.attackCd<=0){e.attackCd=1.2;if(player.invuln<=0)hurt(e.damage);}
  }
  // Bound bone servants orbit you between fights, then rush the nearest foe.
  for(let i=player.servants.length-1;i>=0;i--){const s=player.servants[i];s.life-=dt;s.attackCd-=dt;s.walk+=dt*7;const g=s.group;g.position.y=.08+Math.sin(s.walk)*.12;
    if(s.life<=0){makeBurst(g.position,'#b7dad3',8,.07);world.remove(g);player.servants.splice(i,1);continue;}
    let target=null,td=22;for(const e of enemies){const d=g.position.distanceTo(e.group.position);if(d<td){td=d;target=e;}}
    if(target){const d=target.group.position.clone().sub(g.position);d.y=0;if(td>1.55){d.normalize();g.position.addScaledVector(d,3.2*dt);g.rotation.y=Math.atan2(d.x,d.z)+Math.PI;}else if(s.attackCd<=0){s.attackCd=1.05;damageEnemy(target,18,.2);makeBurst(target.group.position.clone().add(new THREE.Vector3(0,1.2,0)),'#d7e5d6',4,.06);}}
    else{const off=new THREE.Vector3((i===0?-1:1)*1.5,.1,1.4);const goal=player.pos.clone().add(off);const d=goal.sub(g.position);d.y=0;if(d.length()>1.4){d.normalize();g.position.addScaledVector(d,2.4*dt);g.rotation.y=Math.atan2(d.x,d.z)+Math.PI;}}
  }
  for(let i=projectiles.length-1;i>=0;i--){const p=projectiles[i];p.life-=dt;p.mesh.position.addScaledVector(p.vel,dt);p.halo.position.copy(p.mesh.position);p.halo.rotation.z+=dt*5;
    let hit=null;for(const e of enemies)if(e.group.position.distanceTo(p.mesh.position)<(e.type==='brute'?1.1:e.type==='wraith'?1.3:.85)){hit=e;break;}
    if(hit){damageEnemy(hit,p.damage,.45);makeBurst(p.mesh.position,'#98e6e4',10,.08);world.remove(p.mesh);world.remove(p.halo);projectiles.splice(i,1);continue;}
    if(p.life<=0){world.remove(p.mesh);world.remove(p.halo);projectiles.splice(i,1);}
  }
  for(let i=effects.length-1;i>=0;i--){const e=effects[i];if(e.delay){e.delay-=dt;if(e.delay>0)continue;}e.life-=dt;if(e.fade){e.mesh.position.addScaledVector(e.vel,dt);e.mesh.scale.multiplyScalar(1-dt*1.6);if(e.mesh.material.opacity!==undefined)e.mesh.material.opacity=Math.max(0,e.life/e.max);}if(e.ring){const t=1-e.life/e.max;e.mesh.scale.setScalar(1+t*e.expand);e.mesh.material.opacity=Math.max(0,1-t);}if(e.life<=0){world.remove(e.mesh);effects.splice(i,1);}}
  for(let i=pickups.length-1;i>=0;i--){const p=pickups[i];p.life-=dt;p.phase+=dt*2;p.group.position.y=.55+Math.sin(p.phase)*.15;p.group.rotation.y+=dt*1.2;if(p.group.position.distanceTo(player.group.position)<1.25){player.xp+=12;player.souls++;player.mana=Math.min(player.maxMana,player.mana+5);checkLevel();world.remove(p.group);pickups.splice(i,1);sound(590,.09,'sine',.018);}else if(p.life<=0){world.remove(p.group);pickups.splice(i,1);}}
  updateUi();
}
function hurt(amount){player.hp=Math.max(0,player.hp-amount);player.invuln=.68;document.querySelector('#damage-flash').style.opacity='.8';setTimeout(()=>document.querySelector('#damage-flash').style.opacity='0',140);makeBurst(new THREE.Vector3(player.pos.x,1.2,player.pos.z),'#e67b67',8,.08);sound(90,.2,'sawtooth',.045);if(player.hp<=0){player.alive=false;finishGame(false);}}
function updateUi(){
  const hp=player.hp/player.maxHp*100,mana=player.mana/player.maxMana*100;document.querySelector('#health-fill').style.width=`${hp}%`;document.querySelector('#mana-fill').style.width=`${mana}%`;document.querySelector('#health-text').textContent=`${Math.ceil(player.hp)} / ${player.maxHp}`;document.querySelector('#mana-text').textContent=`${Math.floor(player.mana)} / ${player.maxMana}`;
  const need=player.level===1?80:player.level===2?140:220;document.querySelector('#xp-fill').style.width=`${Math.min(100,player.xp/need*100)}%`;document.querySelector('#xp-label').textContent=`${player.xp} / ${need}`;document.querySelector('#level-badge').textContent=String(player.level).padStart(2,'0');document.querySelector('#soul-count').textContent=player.souls;
  document.querySelector('#summon-cooldown').style.transform=`scaleY(${player.summonCd>0?1:0})`;document.querySelector('#nova-cooldown').style.transform=`scaleY(${player.novaCd>0?1:0})`;
  const angle=Math.atan2(player.aim.x,player.aim.z);document.querySelector('#compass-needle').style.transform=`rotate(${angle}rad)`;
  const z=Math.round(-player.pos.z+10),x=Math.round(player.pos.x+70);document.querySelector('#map-coords').textContent=`N ${String(Math.max(0,z)).padStart(2,'0')} · E ${String(Math.max(0,x)).padStart(2,'0')}`;
  const zones=[['THE OLD ROAD',Math.abs(player.pos.x)<9&&player.pos.z<3],['THE WEEPING WOOD',player.pos.x<0&&player.pos.z<0],['HOLLOW FEN',player.pos.x>8&&player.pos.z<0],['THE SUNKEN ALTAR',player.pos.z>5&&player.pos.x>7]];const zone=zones.find(z=>z[1]);document.querySelector('#zone-label').textContent='· '+(zone?zone[0]:'THE ASHEN WILDS');
  drawMap();
}
let mapTimer=0;
function drawMap(){if((mapTimer+=clock.getDelta())<.18)return;mapTimer=0;const c=document.querySelector('#minimap'),ctx=c.getContext('2d'),w=c.width,h=c.height;ctx.clearRect(0,0,w,h);ctx.fillStyle='#19221f';ctx.fillRect(0,0,w,h);
  // subdued cartographic patches and an old-road line
  ctx.fillStyle='#27302a';ctx.beginPath();ctx.ellipse(31,35,43,38,-.4,0,Math.PI*2);ctx.fill();ctx.fillStyle='#25312d';ctx.beginPath();ctx.ellipse(116,102,46,54,.4,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#716c5b';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(75,150);ctx.lineTo(75,0);ctx.stroke();
  for(const o of obelisks){const x=(o.position.x+70)/140*w,y=(o.position.z+70)/140*h;ctx.beginPath();ctx.arc(x,y,4.2,0,Math.PI*2);ctx.fillStyle=o.userData.awakened?'#c3a0eb':'#89d4d7';ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=8;ctx.fill();ctx.shadowBlur=0;}
  for(const e of enemies){const x=(e.group.position.x+70)/140*w,y=(e.group.position.z+70)/140*h;ctx.fillStyle=e.type==='wraith'?'#d18ff2':'#cf7564';ctx.beginPath();ctx.arc(x,y,e.type==='wraith'?3.5:2,0,Math.PI*2);ctx.fill();}
  ctx.fillStyle='#e3c28d';ctx.beginPath();ctx.arc((player.pos.x+70)/140*w,(player.pos.z+70)/140*h,3.5,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#f0d7a8';ctx.lineWidth=1.2;ctx.beginPath();ctx.moveTo((player.pos.x+70)/140*w,(player.pos.z+70)/140*h);ctx.lineTo((player.pos.x+70)/140*w+Math.sin(Math.atan2(player.aim.x,player.aim.z))*7,(player.pos.z+70)/140*h+Math.cos(Math.atan2(player.aim.x,player.aim.z))*7);ctx.stroke();
}

