function aimFromEvent(event){const r=canvas.getBoundingClientRect();pointer.x=((event.clientX-r.left)/r.width)*2-1;pointer.y=-((event.clientY-r.top)/r.height)*2+1;cameraRay.setFromCamera(pointer,camera);const ray=cameraRay.ray;if(Math.abs(ray.direction.y)>.0001){const t=-ray.origin.y/ray.direction.y;if(t>0)aimPoint.copy(ray.origin).addScaledVector(ray.direction,t);}window.mouseActive=true;}
canvas.addEventListener('pointermove',aimFromEvent);
canvas.addEventListener('pointerdown',e=>{if(e.button===0){aimFromEvent(e);if(started&&!ended)fireBolt();}});
canvas.addEventListener('contextmenu',e=>e.preventDefault());
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();keys[k]=true;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(e.repeat)return;if(k==='q')summon();if(k==='e')castNova();if(k===' '||k==='shift')wraithStep();if(k==='f')interact();if(k==='escape'&&started&&!ended)document.querySelector('#help-modal').classList.remove('hidden');});
window.addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false;});
document.querySelector('#start-btn').addEventListener('click',()=>{document.querySelector('#intro-modal').classList.add('hidden');started=true;notify('THE ASHEN WILDS · FIND THE SOUL OBELISKS');sound(260,.3,'sine',.04);});
document.querySelector('#help-btn').addEventListener('click',()=>document.querySelector('#help-modal').classList.remove('hidden'));
document.querySelector('#close-help').addEventListener('click',()=>document.querySelector('#help-modal').classList.add('hidden'));
document.querySelector('#resume-btn').addEventListener('click',()=>document.querySelector('#help-modal').classList.add('hidden'));
document.querySelector('#sound-btn').addEventListener('click',e=>{audioOn=!audioOn;e.currentTarget.textContent=audioOn?'♫':'♪';e.currentTarget.style.opacity=audioOn?'1':'.55';if(audioOn)sound(330,.12);});
document.querySelector('#restart-btn').addEventListener('click',()=>location.reload());
// Simple, generous touch controls for phones and tablets.
const stickZone=document.querySelector('#stick-zone'),knob=document.querySelector('#stick-knob');let stickId=null,stickRect=null;
stickZone.addEventListener('pointerdown',e=>{stickId=e.pointerId;stickZone.setPointerCapture(stickId);stickRect=stickZone.getBoundingClientRect();updateStick(e);});
stickZone.addEventListener('pointermove',e=>{if(e.pointerId===stickId)updateStick(e);});
function updateStick(e){const cx=stickRect.left+stickRect.width/2,cy=stickRect.top+stickRect.height/2,dx=e.clientX-cx,dy=e.clientY-cy,r=34,len=Math.hypot(dx,dy),s=len>r?r/len:1;const x=dx*s,y=dy*s;knob.style.transform=`translate(${x}px,${y}px)`;window.touchMove={x:x/r,y:y/r};}
function releaseStick(){stickId=null;window.touchMove={x:0,y:0};knob.style.transform='translate(0,0)';}
stickZone.addEventListener('pointerup',releaseStick);stickZone.addEventListener('pointercancel',releaseStick);window.touchMove={x:0,y:0};
document.querySelector('#mobile-attack').addEventListener('pointerdown',e=>{e.preventDefault();if(started)fireBolt();});document.querySelector('#mobile-summon').addEventListener('pointerdown',e=>{e.preventDefault();summon();});document.querySelector('#mobile-nova').addEventListener('pointerdown',e=>{e.preventDefault();castNova();});document.querySelector('#mobile-interact').addEventListener('pointerdown',e=>{e.preventDefault();interact();});
function resize(){const w=window.innerWidth,h=window.innerHeight;renderer.setSize(w,h);renderer.setPixelRatio(Math.min(window.devicePixelRatio||1,1.7));camera.aspect=w/h;camera.updateProjectionMatrix();}
window.addEventListener('resize',resize);
camera.position.set(player.pos.x,player.pos.y+22,player.pos.z+19);camera.lookAt(player.pos.x,1.2,player.pos.z-1.6);drawMap();
function animate(){requestAnimationFrame(animate);const dt=Math.min(.04,clock.getDelta());if(started)update(dt);else{worldTime+=dt;player.rig.orb.material.emissiveIntensity=2+Math.sin(worldTime*4)*.7;camera.position.lerp(new THREE.Vector3(player.pos.x,player.pos.y+22,player.pos.z+19),1-Math.pow(.002,dt));camera.lookAt(player.pos.x,1.2,player.pos.z-1.6);for(const o of obelisks)o.userData.rune.material.emissiveIntensity=1.1+Math.sin(worldTime*2.7+o.userData.index)*.7;}
  renderer.render(scene,camera);
}
